from ..widgets.widgets import BetterCanvas, EntryBoxWithLabel
from ..widgets.widgets import Tooltip
from ..utils.logger import logger

import tkinter as tk
import itertools
from tkinter import ttk

from PIL import Image, ImageTk
from pathlib import Path
import os
import re
from copy import copy


class RModsFrame(ttk.Frame):

    def __init__(self, parent, model, *args, **kwargs):
        super().__init__(parent, name="rmods_frame_section", borderwidth=1, relief="ridge", *args, **kwargs)
        self.model = model
        self.available_rmods = list(model.rmods_info)
        self.available_ports_per_bbmods = copy(model.bbmods_smods_info['BBMODS'])
        self.available_ports_per_bbmods['ASOE'] = {'rf_ports_count': 12}
        self.available_ports_per_bbmods['ASOF'] = {'rf_ports_count': 12}
        self.available_ports_per_bbmods_with_cus = model.cus_ports
        self.available_bbmods = []
        self.available_bbmods_list_with_link = {}
        self.rmods_dictionary = {}
        self.rmods_iterator = 1
        self.custom_enabled = False
        self.selected_topology = None
        self.enb_id = None
        self.icons = self.__get_icons()
        self._initial_setup()

    def get_configuration(self):
        return {i: rmod.get_configuration() for i, rmod in self.rmods_dictionary.items() if rmod.is_fully_configured}

    def _get_configuration(self):
        return {i: rmod._get_configuration() for i, rmod in self.rmods_dictionary.items()}

    def get_validation_log(self):
        return [f"RMOD-{i} is not configured" for i, rmod in self.rmods_dictionary.items() if not rmod.is_fully_configured]

    def _initial_setup(self):
        rmods_label = ttk.Label(
            self, text="LINK TO                     PORT                   TYPE", font=('Helvetica', 12, 'bold'), name="rmods_frame_label"
        )
        add_new_rmod_button = ttk.Button(
            self, text="Ad", command=lambda: self._add_rmod(event=True), image=self.icons['rmod_plus'], name='add_rmod_frame'
        )
        Tooltip(add_new_rmod_button, text='Add RMOD')
        separator = ttk.Separator(
            self, orient='horizontal', name="header_separator"
        )
        rmods_canvas = BetterCanvas(
            self, bg="white", borderwidth=0, height=636, name="rmods_canvas", width=368
        )
        rmods_scrollbar = ttk.Scrollbar(
            self, orient=tk.VERTICAL, command=rmods_canvas.yview, name="rmods_scrollbar"
        )
        rmods_frame = ttk.Frame(
            rmods_canvas, name="rmods_frame"
        )

        rmods_canvas.create_window((0, 0), window=rmods_frame)
        rmods_canvas.configure(yscrollcommand=rmods_scrollbar.set)

        rmods_label.grid(column=0, row=0, sticky="sw", padx=(12, 0), ipady=10, columnspan=4)
        add_new_rmod_button.grid(row=0, column=3, padx=(343, 0), sticky="nsew")
        separator.grid(row=1, sticky="ew", columnspan=4)
        rmods_canvas.grid(row=2, sticky="nsew", columnspan=4)
        rmods_scrollbar.grid(row=2, column=3, sticky="nse")

        def update_canvas(_event):
            rmods_canvas.configure(scrollregion=rmods_canvas.bbox("all"))
            if rmods_canvas.yview() == (0.0, 1.0):
                rmods_canvas.yview_moveto(1.0)
        rmods_frame.bind("<Configure>", update_canvas)  # is it necessary?

        rmods_canvas.bind('<Enter>', self._bound_to_mousewheel)
        rmods_canvas.bind('<Leave>', self._unbound_to_mousewheel)

    @property
    def rmods_canvas(self):
        return self.children['rmods_canvas']

    @property
    def rmods_scrollbar(self):
        return self.children['rmods_scrollbar']

    def _bound_to_mousewheel(self, _event):
        self.rmods_canvas.bind_all("<Button-4>", lambda event: self.rmods_canvas.yview_scroll(int(-1 * event.num), 'units'))
        self.rmods_canvas.bind_all("<Button-5>", lambda event: self.rmods_canvas.yview_scroll(int(event.num), 'units'))
        self.unbind_class("TCombobox", "<ButtonPress-4>")
        self.unbind_class("TCombobox", "<ButtonPress-5>")

    def _unbound_to_mousewheel(self, _event):
        self.rmods_canvas.unbind_all("<Button-4>")
        self.rmods_canvas.unbind_all("<Button-5>")

    def _add_rmod(self, rmod_name='', connections=None, event=False):
        number_of_rmods = len(self.rmods_dictionary)
        next_rmod_id = number_of_rmods + 1

        parent = self.children['rmods_canvas'].children['rmods_frame']
        singel_rmod_frame = SingleRmodFrame(
            parent, rmod_name, connections, self.available_rmods, self.available_bbmods,
            icons=self.icons, text=f"RMOD-{next_rmod_id}", borderwidth=0, font=('Helvetica 9'), bg='white', name=f"rmod_{self.rmods_iterator}"
        )
        self.rmods_dictionary[next_rmod_id] = singel_rmod_frame
        singel_rmod_frame.grid(column=0, row=next_rmod_id, sticky="new", columnspan=4)
        self.rmods_iterator += 1
        if event:
            self.event_generate('<<PostAddRmod>>')
            logger.info(f"Adding RMOD to {self}")

    def reset(self, event=True):
        new_rmods_dictionary = {}
        for i, rmod in sorted(self.rmods_dictionary.items(), key=lambda item: item[0]):
            if i == 1:
                rmod._reset(event)
                new_rmods_dictionary[1] = rmod
            else:
                rmod.destroy()
        self.rmods_dictionary = new_rmods_dictionary

    def full_reset(self):
        for i, rmod in sorted(self.rmods_dictionary.items(), key=lambda item: item[0]):
            rmod.destroy()
        self.rmods_dictionary = {}

    def rearrange(self):
        new_rmods_dictionary = {}
        for i, (idx, rmod) in zip(itertools.count(1), sorted(self.rmods_dictionary.items(), key=lambda item: item[0])):
            rmod.grid(row=i, sticky="new", column=0, columnspan=2)
            new_rmods_dictionary[i] = rmod
            rmod.configure(text=f"RMOD-{i}")
        self.rmods_scrollbar.set(0, 1)
        self.rmods_dictionary = new_rmods_dictionary

    def __get_icons(self):
        graphic_src_path = Path(os.path.abspath(__file__)).parents[1] / "graphics"

        rmod_plus = Image.open(graphic_src_path / "rmod_plus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        rmod_plus_image = ImageTk.PhotoImage(rmod_plus, master=self)

        rmod_minus = Image.open(graphic_src_path / "rmod_minus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        rmod_minus_image = ImageTk.PhotoImage(rmod_minus)

        plus_sign = Image.open(graphic_src_path / "large_plus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        plus_sign_image = ImageTk.PhotoImage(plus_sign)

        minus_sign = Image.open(graphic_src_path / "large_minus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        minus_sign_image = ImageTk.PhotoImage(minus_sign)

        refresh_sign = Image.open(graphic_src_path / "refresh_sign.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        refresh_sign_image = ImageTk.PhotoImage(refresh_sign)

        return {
            'rmod_plus': rmod_plus_image,
            'rmod_minus': rmod_minus_image,
            'plus_sign': plus_sign_image,
            'minus_sign': minus_sign_image,
            'refresh_sign': refresh_sign_image
        }

    def hide_grid_cus_port_entry_box(self):
        for i, rmod in sorted(self.rmods_dictionary.items(), key=lambda item: item[0]):
            if self.custom_enabled:
                rmod.grid_cus_port_entry_box()
            else:
                rmod.hide_cus_port_entry_box()

    def get_available_bbmods_list_with_link(self, available_bbmods_list):
        if self.custom_enabled:
            return {
                bbmod: [
                    f"RF{i}" for i in range(1, int(self.available_ports_per_bbmods[re.search(r'(^\S+).*', bbmod).group(1)]['rf_ports_count']) + 1)
                ]
                for bbmod in available_bbmods_list if not bbmod.startswith(' ')
            }
        regex = r'((?:BB|S)MOD-\d+)'
        self.available_ports_per_bbmods_with_cus = self.model.cus_ports

        key_prefix = None
        enb_key = f'ENB{self.enb_id}'
        gnb_key = f'GNB{self.enb_id}'

        if enb_key in self.available_ports_per_bbmods_with_cus:
            key_prefix = enb_key
        elif gnb_key in self.available_ports_per_bbmods_with_cus:
            key_prefix = gnb_key
        else:
            key_prefix = enb_key

        return {
            bbmod: list(self.available_ports_per_bbmods_with_cus[key_prefix][re.search(regex, bbmod).group(1)])
            for bbmod in available_bbmods_list if not bbmod.startswith(' ')
        }

    def remove_occupied_links(self, occupied_bbmods, available_bbmods_list_with_link):
        for _, rmod in sorted(self._get_configuration().items(), key=lambda item: item[0]):
            k = next(iter(rmod))
            for connection_info in rmod[k].values():
                (bbmod, link) = connection_info
                if bbmod and link and bbmod in available_bbmods_list_with_link:
                    occupied_bbmods.append(bbmod)
                    available_bbmods_list_with_link[bbmod].remove(link)

    def set_links_without_cus(self):
        """
        Set links when Custom Config is Enabled.
        """
        for i, rmod in sorted(self.rmods_dictionary.items(), key=lambda item: item[0]):
            for i, connection in sorted(rmod.connection_dict.items(), key=lambda item: item[0]):
                current_value = connection.children['port_combobox'].get()
                if current_value:
                    connection.children['port_combobox'].set(re.search(r'\S+', current_value).group())

    def update_available_bbmods_for_rmods(self, available_bbmods_list):
        available_bbmods_list_with_link = self.get_available_bbmods_list_with_link(available_bbmods_list)

        occupied_bbmods = []
        self.remove_occupied_links(occupied_bbmods, available_bbmods_list_with_link)
        available_bbmods_list = [bbmod for bbmod, links in available_bbmods_list_with_link.items()]
        for i, rmod in sorted(self.rmods_dictionary.items(), key=lambda item: item[0]):
            for i, connection in sorted(rmod.connection_dict.items(), key=lambda item: item[0]):
                bbmod_type_combobox = connection.children['bbmod_type']
                bbmod_type = bbmod_type_combobox.get()
                if bbmod_type not in available_bbmods_list and bbmod_type not in occupied_bbmods:
                    connection._reset()
                bbmod_type_combobox['values'] = available_bbmods_list

        self.available_bbmods_list_with_link = available_bbmods_list_with_link

    def update_links_for_selected_bbmod(self, event, available_bbmods_list):
        ###############
        # selected_bbmod = event.widget.get()
        event.widget.master.children['port_combobox'].set('')
        available_bbmods_list_with_link = self.get_available_bbmods_list_with_link(available_bbmods_list)
        occupied_bbmods = []
        self.remove_occupied_links(occupied_bbmods, available_bbmods_list_with_link)
        self.available_bbmods_list_with_link = available_bbmods_list_with_link

        ###############
        # available_links = self.available_bbmods_list_with_link[selected_bbmod]
        event.widget.master.children['port_combobox'].set("")
        self.update_available_links_bbmod(event, available_bbmods_list)

    def update_available_links_bbmod(self, event, available_bbmods_list):

        available_bbmods_list_with_link = self.get_available_bbmods_list_with_link(available_bbmods_list)
        occupied_bbmods = []
        self.remove_occupied_links(occupied_bbmods, available_bbmods_list_with_link)
        self.available_bbmods_list_with_link = available_bbmods_list_with_link

        # selected_link = event.widget.get()
        # selected_bbmod = event.widget.master.children['bbmod_type'].get()
        for i, rmod in sorted(self.rmods_dictionary.items(), key=lambda item: item[0]):
            for i, connection in sorted(rmod.connection_dict.items(), key=lambda item: item[0]):
                current_value = connection.children['port_combobox'].get()
                current_selected_bbmod = connection.children['bbmod_type'].get()
                if current_selected_bbmod:
                    available_links = sorted(filter(
                        lambda x: bool(x), self.available_bbmods_list_with_link[current_selected_bbmod] + [current_value]
                    ))
                    connection.children['port_combobox']['values'] = available_links
                else:
                    connection.children['port_combobox']['values'] = []

    def reset_connection_after_bbmod_deletion(self, bbmod_name, available_bbmods_list, prv_available_bbmods_list, idx):
        new_names_map = {}
        for i, rmod in sorted(self.rmods_dictionary.items(), key=lambda item: item[0]):
            for i, connection in sorted(rmod.connection_dict.items(), key=lambda item: item[0]):
                bbmod_type_combobox = connection.children['bbmod_type']
                current_name = bbmod_type_combobox.get()
                if current_name == bbmod_name:
                    connection._reset()
                    bbmod_type_combobox['values'] = available_bbmods_list
                    if bbmod_name in self.available_bbmods_list_with_link:
                        self.available_bbmods_list_with_link.pop(bbmod_name)
                else:
                    bbmod_type_combobox['values'] = available_bbmods_list
                    if current_name:
                        current_bbmod_index = int(re.search(r'(\d+)', current_name).group(1))
                        if current_bbmod_index >= idx + 1:
                            new_name = re.sub(r'(\d+)', str(current_bbmod_index - 1), current_name)
                            bbmod_type_combobox.set(new_name)
                            new_names_map[current_name] = new_name
        self.available_bbmods_list_with_link = {
            (k if k not in new_names_map else new_names_map[k]): v
            for k, v in self.available_bbmods_list_with_link.items()
        }

    def update_available_bbmods_for_rmods_after_connection_reset(self, available_bbmods_list):
        available_bbmods_list_with_link = self.get_available_bbmods_list_with_link(available_bbmods_list)
        occupied_bbmods = []
        self.remove_occupied_links(occupied_bbmods, available_bbmods_list_with_link)

        available_bbmods_list = [bbmod for bbmod, links in available_bbmods_list_with_link.items()]
        for _, rmod in sorted(self.rmods_dictionary.items(), key=lambda item: item[0]):
            for _, connection in sorted(rmod.connection_dict.items(), key=lambda item: item[0]):
                bbmod_type_combobox = connection.children['bbmod_type']
                bbmod_type = bbmod_type_combobox.get()
                connection.children['bbmod_type']['values'] = available_bbmods_list
                if not bbmod_type:
                    connection.children['port_combobox'].set('')
                    connection.children['port_combobox']['values'] = []
                    continue

                current_port_value = connection.children['port_combobox'].get()
                available_links = sorted(filter(lambda x: bool(x), available_bbmods_list_with_link[bbmod_type] + [current_port_value]))
                connection.children['port_combobox']['values'] = available_links

        self.available_bbmods_list_with_link = available_bbmods_list_with_link


class SingleRmodFrame(tk.LabelFrame):
    def __init__(self, parent, rmod_name, connections, available_rmods, available_bbmods, icons, **kwargs):
        super().__init__(parent, labelanchor='nw', **kwargs)
        self.available_rmods = available_rmods
        self.available_bbmods = available_bbmods
        self.icons = icons
        self.connection_dict = {}
        self.connection_iterator = 2
        if connections is None:
            connections = [('', '')]
        self._initial_setup(rmod_name, connections)

    @property
    def is_fully_configured(self):
        if self.connection_dict[1].children['rmod_type_combobox'].get():
            for i, connection in self.connection_dict.items():
                (bbmod, link) = connection.get_configuration()
                if bbmod and link:
                    continue
                return False
            return True
            # return not self.master.master.master.custom_enabled or bool(re.fullmatch(r'\d\.\d', self.cus_port.get_text()))
        else:
            return False

    def get_configuration(self):
        return {
            self.connection_dict[1].children['rmod_type_combobox'].get(): {
                i: connection.get_configuration()for i, connection in self.connection_dict.items()
            },
            'cus_port': self.cus_port.get_text()
        }

    def _get_configuration(self):
        return {
            self.connection_dict[1].children['rmod_type_combobox'].get(): {
                i: connection.get_configuration() for i, connection in self.connection_dict.items()
            }
        }

    def _initial_setup(self, rmod_name, connections):
        rmod_connection_frame = ttk.Frame(
            self, borderwidth=0, relief="flat", name="rmod_connection_frame"
        )
        rmod_connection_frame.grid(row=0, column=0, sticky="new", columnspan=4)
        available_rmods = [rmod for rmod, links in self.__get_rmods_frame().available_bbmods_list_with_link.items()]
        first_rmod_connection = FirstRmodConnection(
            rmod_connection_frame, rmod_name, connections[0], self.available_rmods, available_rmods,
            self.icons, borderwidth=0, relief="ridge", name="first_rmod_connection"
        )
        self.connection_dict[1] = first_rmod_connection
        first_rmod_connection.grid(sticky="new", pady=2, column=0, columnspan=4)

        delete_rmod_button = ttk.Button(
            self, text="Delete RMOD", name="delete_rmod", command=lambda: self._destroy_rmod(event=True), image=self.icons['rmod_minus']
        )
        Tooltip(delete_rmod_button, text='Delete/Reset RMOD')

        reset_rmod_button = ttk.Button(
            self, text="Reset RMOD", name="reset_rmod", command=lambda: self._reset(event=True), image=self.icons['refresh_sign']
        )
        Tooltip(reset_rmod_button, text='Reset RMOD!')
        self.cus_port = EntryBoxWithLabel(self)
        delete_rmod_button.grid(row=2, column=0, sticky="nsw")
        if self.master.master.master.custom_enabled:
            reset_rmod_button.grid(row=2, column=1, sticky="nsw", padx=(0, 110))
            self.cus_port.grid(row=2, column=2)
            Tooltip(self.cus_port, text='Set CUS port - X-A.B, where X is CUS number, A is port at BBMOD side and B is port at CUS side, e.g. 1-2.5')
        else:
            reset_rmod_button.grid(row=2, column=1, sticky="nsw", padx=(0, 280))
        separator_h = ttk.Separator(self, orient='horizontal')
        separator_h.grid(row=3, sticky="ew", columnspan=12)

        for connection in connections[1:]:
            self._add_connection_frame(connection)

    def rearrange(self):
        new_connections_dict = {}
        for i, (idx, connection) in zip(itertools.count(1), sorted(self.connection_dict.items(), key=lambda item: item[0])):
            new_connections_dict[i] = connection
            if i == 1:
                continue
            connection.grid(row=i, sticky="new", pady=2, column=0, columnspan=2)
        self.connection_dict = new_connections_dict

    def grid_cus_port_entry_box(self):
        self.children['reset_rmod'].grid(row=2, column=1, sticky="nsw", padx=(0, 130))
        self.cus_port.grid(row=2, column=2, padx=(0, 17))
        Tooltip(self.cus_port, text='Set CUS port - X-A.B, where X is CUS number, A is port at BBMOD side and B is port at CUS side, e.g. 1-2.5')

    def hide_cus_port_entry_box(self):
        self.cus_port.forget()
        self.children['reset_rmod'].grid(row=2, column=1, sticky="nsw", padx=(0, 280))

    def _destroy_rmod(self, event=False):

        number_of_configured_rmods = len(self.__get_rmods_frame().rmods_dictionary)
        if number_of_configured_rmods > 1:
            if event:
                self.event_generate('<<PriorDeleteRmod>>')
                logger.info(f"Deleting RMOD {self}")
            self._destroy(event)
        else:
            logger.info(f"Deleting RMOD {self}")
            self._reset(event)

    def _destroy(self, event=True):
        configured_rmods = self.__get_rmods_frame().rmods_dictionary
        current_id = self._get_current_id(configured_rmods)
        configured_rmods.pop(current_id)
        self.forget()
        self.__get_rmods_frame().rearrange()
        if event:
            self.event_generate('<<PostDeleteRmod>>')
        self.destroy()

    def _reset(self, event=False):
        if event:
            self.event_generate('<<PriorResetRmod>>')
        new_connection_dict = {}
        for i, connection in self.connection_dict.items():
            if i == 1:
                connection._reset()
                new_connection_dict[i] = connection
            if i > 1:
                connection.destroy()
        self.connection_dict = new_connection_dict
        self.cus_port.delete(0, tk.END)
        if event:
            logger.info(f"Reseting RMOD {self}")
            self.event_generate('<<PostResetRmod>>')

    def _get_current_id(self, connections):
        for id_, connection in connections.items():
            if connection == self:
                return id_

    def __get_rmod_connection_frame(self):
        return self.children['rmod_connection_frame']

    def __get_rmods_frame(self):
        return self.master.master.master


class FirstRmodConnection(ttk.Frame):

    def __init__(self, parent, rmod_name, connection, available_rmods, available_bbmods, icons, *args, **kwargs):
        super().__init__(parent, *args, **kwargs)
        self.available_rmods = available_rmods
        self.available_bbmods = available_bbmods
        self.icons = icons
        self._initial_setup(rmod_name, connection)

    def get_configuration(self):
        return self.children['bbmod_type'].get(), self.children['port_combobox'].get()

    def _initial_setup(self, rmod_name, connection):
        bbmod_type = ttk.Combobox(
            self, values=self.available_bbmods, width=16, state="readonly", name="bbmod_type"
        )
        port_combobox = ttk.Combobox(
            self, values=[], width=12, state="readonly", name="port_combobox"
        )
        rmod_type = ttk.Combobox(
            self, values=self.available_rmods, width=8, state="readonly", name="rmod_type_combobox"
        )
        Tooltip(bbmod_type, text='Set available BBMOD')
        Tooltip(port_combobox, text='Set BBMOD port; BBMOD must be selected first')
        Tooltip(rmod_type, text='Set RMOD')

        bbmod_name, link = connection
        bbmod_type.set(bbmod_name)
        port_combobox.set(link)
        rmod_type.set(rmod_name)

        bbmod_type.grid(row=0, column=0)
        port_combobox.grid(row=0, column=1)
        rmod_type.grid(row=0, column=2)

    def _reset(self):
        for child in self.winfo_children():
            if isinstance(child, ttk.Combobox):
                child.set("")
                if 'port_combobox' in str(child):
                    child['values'] = []
